   /**
    * Calculate filter information based on desired interval
    * This calculates a clock prescaler so that the filter interval is at least the given value.
    *
    * @param[in]     interval   Desired filter interval
    * @param[inout]  psr        Input: psr.pcs Output: updated with psr.prescale and psr.pbyp
    *
    * @return E_NO_ERROR      => Success
    * @return E_ILLEGAL_PARAM => Failed to find suitable values for psr.prescale and psr.pbyp
    */
   ErrorCode calculateFilterValues(Seconds interval, uint8_t &psr) const {
   
      float    inputClock = LptmrBasicInfo::getInputClockFrequency(LptmrClockSel(psr&LPTMR_PSR_PCS_MASK));
      int      prescaleFactor=1;
      uint32_t prescalerValue=0;
      while (prescalerValue<=16) {
         if ((float)(interval*prescaleFactor) < inputClock) {
            psr  = (psr&LPTMR_PSR_PCS_MASK)|LPTMR_PSR_PRESCALE(prescalerValue-1)|LPTMR_PSR_PBYP(prescalerValue==0);
            return E_NO_ERROR;
         }
         prescalerValue++;
         prescaleFactor <<= 1;
      }
      // Too long a duration
      return setAndCheckErrorCode(E_TOO_LARGE);
   }
   
   /**
    * Set period of timer.
    *
    * @param[in]  period Period in seconds as a float
    *
    * @note Will enable and adjust the pre-scaler to appropriate value.

    *       The clock source should be selected by setClock() before using this function.
    *
    * @return E_NO_ERROR      => Success
    * @return E_ILLEGAL_PARAM => Failed to find suitable values for psr.prescale and psr.pbyp
    */
   ErrorCode setPeriod(Seconds period) const {
   
      uint8_t  psr = lptmr->PSR;
      uint32_t cmr;
      ErrorCode rc = LptmrBasicInfo::calculateDurationValues(period, psr, cmr);
      if (rc != E_NO_ERROR) {
         return rc;
      }
      // Disable before changing clock
      uint32_t csr = lptmr->CSR;
      lptmr->CSR   = csr&~LPTMR_CSR_TEN_MASK;
      (void)(lptmr->CSR);
   
      lptmr->CMR  = cmr;
      lptmr->PSR  = psr;
   
      lptmr->CSR  = csr;
   
      return E_NO_ERROR;
   }
   
   /**
    * Set glitch filter interval.
    * This adjusts the clock prescaler so that the filter interval is at least the given value.
    *
    * @param[in]  interval Interval in seconds as a float
    *
    * @note Will enable and adjust the pre-scaler to appropriate value.

    *       The clock source should be selected by setClock() before using this function.
    *
    * @return E_NO_ERROR      => Success
    * @return E_ILLEGAL_PARAM => Failed to find suitable values for PBYP & PRESCALE
    */
   ErrorCode setFilterInterval(Seconds interval) const {
   
      uint8_t  psr = lptmr->PSR;
   
      ErrorCode rc = calculateFilterValues(interval, psr);
      if (rc != E_NO_ERROR) {
         return rc;
      }
      // Disable LPTMR before prescale change
      uint32_t csr = lptmr->CSR;
      lptmr->CSR   = csr&~LPTMR_CSR_TEN_MASK;
      (void)(lptmr->CSR);
   
      lptmr->PSR  = psr;
   
      lptmr->CSR  = csr;
   
      return E_NO_ERROR;
   }
   
   /**
    * Get timer counter value
    *
    * @return Timer value in ticks.
    */
   Ticks getCounterValue() const {
      // It is necessary to write to the CNR to capture current value
      lptmr->CNR = 0;
      return (Ticks)(lptmr->CNR);
   }
   
   /**
    * Restarts the counter
    * This restarts the timer by disabling and re-enabling with the same configuration
    */
   void restart() const {
      uint32_t csr = lptmr->CSR;
      lptmr->CSR   = csr&~LPTMR_CSR_TEN_MASK;
      lptmr->CSR   = csr;
   }
   
   /**
    * Class used to do initialisation of LPTMR
    */
   class Init {
   
   private:
      /**
       * Prevent implicit parameter conversions
       */
      template <typename... Types>
      constexpr Init(Types...) = delete;
   
      /**
       * No Copy Constructor
       */
      constexpr Init(const Init &other) = delete;
   
   protected:
      /**
       * Default Constructor
       */
      constexpr Init() = default;
   
   public:
      // Timer Compare Interval (lptmr_cmrPeriod)
      Seconds cmrperiod = 0_s;

      // Timer Compare Value (lptmr_cmr_compare)
      uint16_t cmr = 0;

      // Prescaler Value (lptmr_psr_prescaler)
      // Clock source for LPTMR (lptmr_psr_pcs)
      uint8_t psr = 0;

      // Timer action on event (lptmr_csr_tie)
      // Counter Action on Compare Event (lptmr_csr_tfc)
      uint8_t csr = 0;

   }; // class LptmrBasicInfo::Init
   
   /**
    * Class used to do initialisation of LPTMR in Time Interval Mode
    *
    * This class has a templated constructor that accepts various values:
    *
    * @note This constructor may be used to create a const instance in ROM
    *
    * Example:
    * @code
    * %(static)const Lptmr0::TimeIntervalModeInit lptmrInit {
    *    LptmrResetOn_Compare,    // Timer Free-Running Counter enable
    *    LptmrInterrupt_Disabled, // Timer interrupt enable
    *    LptmrClockSel_Oscerclk,  // Clock Source
    *    LptmrPrescale_Direct,    // Prescaler Value
    *    100_ms,                  // Timer Compare Register
    * };
    *
    * // Initialise LPTMR0 in Time Interval mode using values specified above
    * Lptmr0.configure(lptmrInit)
    * @endcode
    */
   class TimeIntervalModeInit : public Init {
   
   private:
      /**
       * No Copy Constructor
       */
      constexpr TimeIntervalModeInit(const Init &other) = delete;
   
   public:
   
      /**
       * Default Constructor
       */
      constexpr TimeIntervalModeInit() : Init() {
   
         csr = (csr & ~LPTMR_CSR_TMS_MASK) | LptmrMode_TimeInterval;
      }
   
      /**
       * Constructor for Timer action on event
       * (lptmr_csr_tie)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param lptmrEventAction Enables LPTMR interrupts
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(LptmrEventAction lptmrEventAction, Types... rest) : TimeIntervalModeInit(rest...) {
   
         csr = (csr&~LPTMR_CSR_TIE_MASK) | uint32_t(lptmrEventAction);
      }
   
      /**
       * Constructor for Counter Action on Compare Event
       * (lptmr_csr_tfc)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param lptmrCounterActionOnEvent Counter action when compare event occurs
       *        The counter can continue counting or be reset to zero.
       *        Should only be altered when timer is disabled.
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(LptmrCounterActionOnEvent lptmrCounterActionOnEvent, Types... rest) : TimeIntervalModeInit(rest...) {
   
         csr = (csr&~LPTMR_CSR_TFC_MASK) | uint32_t(lptmrCounterActionOnEvent);
      }
   
      /**
       * Constructor for Prescaler Value
       * (lptmr_psr_prescaler)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param lptmrPrescale Configures the size of the Prescaler in Time Interval mode
       *        Should only be altered when timer is disabled.
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(LptmrPrescale lptmrPrescale, Types... rest) : TimeIntervalModeInit(rest...) {
   
         psr = (psr&~(LPTMR_PSR_PBYP_MASK|LPTMR_PSR_PRESCALE_MASK)) | uint32_t(lptmrPrescale);
      }
   
      /**
       * Constructor for Clock source for LPTMR
       * (lptmr_psr_pcs)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param lptmrClockSel Selects the clock source for LPTMR
       *        Should only be altered when timer is disabled.
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(LptmrClockSel lptmrClockSel, Types... rest) : TimeIntervalModeInit(rest...) {
   
         psr = (psr&~LPTMR_PSR_PCS_MASK) | uint32_t(lptmrClockSel);
      }
   
      /**
       * Constructor for Timer Compare Value
       * (lptmr_cmr_compare)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param ticks Comparison value
       *        The timer comparison flag is set when the counter reaches this value and increments. 
       *        The hardware trigger will assert until the next time the counter increments. 
       *        This value determines the period in TimeInterval mode or the event time in Pulse Counting mode
       *        The CMR must only be altered when timer is disabled or when TCF is set.
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(const Ticks& ticks, Types... rest) : TimeIntervalModeInit(rest...) {
   
         cmr = (cmr&~LPTMR_CMR_COMPARE_MASK) | uint32_t(LPTMR_CMR_COMPARE(ticks));
      }
   
      /**
       * Constructor for Timer Compare Interval
       * (lptmr_cmrPeriod)
       *
       * @tparam   Types
       * @param    rest
       *
       * @param seconds Comparison value
       *        The timer comparison flag is set when the counter reaches this value and increments. 
       *        The hardware trigger will assert until the next time the counter increments. 
       *        This value determines the period in TimeInterval mode or the event time in Pulse Counting mode
       */
      template <typename... Types>
      constexpr TimeIntervalModeInit(const Seconds& seconds, Types... rest) : TimeIntervalModeInit(rest...) {
   
         cmrperiod = seconds;
      }
   
   }; // class LptmrBasicInfo::TimeIntervalModeInit
   
