   template<typename T>
   using CallbackWrapper = USBDM::CallbackWrapper<T, Lptmr0Info>;
   
   /**
    * Function to wrap a member function as a static callback function
    * Example:
    * @code
    * class AClass {
    * public:
    *    int y;
    *
    *    // Member function used as callback
    *    // This function must match CallbackFunction
    *    void callbackFuction() {
    *       ...;
    *    }
    * };
    * ...
    *    AClass *tester = new AClass{};
    *
    *    auto cb = Lptmr0::wrapCallback(tester, &AClass::callbackFuction);
    *    Lptmr0::setCallback(cb);
    *   @endcode
    *
    * @tparam T               Type of class containing callback (inferred)
    *
    * @param classInstance    Pointer to instance of class
    * @param memberFunction   Pointer to the member function
    *
    * @return  Wrapper
    */
   template<typename T>
   static auto wrapCallback(T *classInstance, void (T::*memberFunction)()) {
      static CallbackWrapper<T> sClass(classInstance, memberFunction);
      return sClass.callback;
   }
   
   /**
    * LPTMR interrupt handler -  Calls LPTMR callback
    */
   static void irqHandler() {
   
      // Execute call-back
      sCallback();
   }
   
   /** Callback function for Lptmr0 */
   static inline CallbackFunction sCallback = unhandledCallback; // LPTMR0_IRQn;
   
   /**
    * Set interrupt callback function.
    *
    * @param  lptmrCallback Callback function to execute on interrupt
    *                             Use nullptr to remove callback.
    */
   static void setCallback(CallbackFunction lptmrCallback) {
      if (lptmrCallback == nullptr) {
         lptmrCallback = unhandledCallback;
      }
      // Allow either no handler set yet, setting same handler or removing handler
      usbdm_assert(
            (sCallback == unhandledCallback) ||
            (sCallback == lptmrCallback) ||
            (lptmrCallback == unhandledCallback),
            "Handler already set");
      sCallback = lptmrCallback;
   }
   
   /**
    *  Enable clock to Lptmr0
    */
   static void enableClock() {
      SIM->SCGC5 = SIM->SCGC5 | SIM_SCGC5_LPTMR0_MASK;
   }
   
   /**
    *  Disable clock to Lptmr0
    */
   static void disableClock() {
      SIM->SCGC5 = SIM->SCGC5 & ~SIM_SCGC5_LPTMR0_MASK;
   }
   
   /**
    * Basic enable of Lptmr0
    * Includes enabling clock and configuring all mapped pins if mapPinsOnEnable is selected in configuration
    */
   static void enable() {
      enableClock();
      configureAllPins();
   }
   
   /**
    * Disables Lptmr0
    */
   static void disable() {
   
      
      disableNvicInterrupts();
      disableAllPins();
      disableClock();
   }
   
